mapper.update:
update proj_review_base_info
set declared_amount=#{declaredAmount}
where id=#{projectId}

mapper.select:
select a.*
from proj_review_base_info a

    and a.client_id=#{dto.clientId}
    and a.proj_name like CONCAT('%',#{dto.projName},'%')
    and a.proj_code like CONCAT('%',#{dto.projCode}, '%')
    
    and a.biz_type = #{dto.bizType}
    and a.biz_dept_id=#{dto.bizDeptId}
    and a.proj_sponsor_user_id=#{dto.projSponsorUserId}
    
        and json_contains(a.proj_cosponsor_user_ids, CONVERT(#{dto.projCosponsorUserId},CHAR))
    
    and a.proj_review_status=#{dto.projReviewStatus}
    and
        a.proj_review_process_status=#{dto.projReviewProcessStatus}
    
    and a.create_time >= #{dto.createFrom}
    and a.create_time <= #{dto.createTo}
    and a.update_time >= #{dto.updateFrom}
    and a.update_time <= #{dto.updateTo}
    

order by update_time desc
